import{_ as r}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as e,c as l,a3 as i}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"ようこそ","description":"MiniTavern Ultra ガイド — 一文でキャラカード、または v2/v3。GPT、Claude、OpenRouter かローカルモデル。ワールドブック、正規表現、プリセット、画像の理解と画像返信、バックアップとチャットアーカイブ。","frontmatter":{"title":"ようこそ","description":"MiniTavern Ultra ガイド — 一文でキャラカード、または v2/v3。GPT、Claude、OpenRouter かローカルモデル。ワールドブック、正規表現、プリセット、画像の理解と画像返信、バックアップとチャットアーカイブ。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"ようこそ · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra ガイド — 一文でキャラカード、または v2/v3。GPT、Claude、OpenRouter かローカルモデル。ワールドブック、正規表現、プリセット、画像の理解と画像返信、バックアップとチャットアーカイブ。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja"}]]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1792058564000}'),n={name:"ja/index.md"};function o(u,a,s,d,h,g){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="ようこそ" tabindex="-1">ようこそ <a class="header-anchor" href="#ようこそ" aria-label="Permalink to &quot;ようこそ&quot;">​</a></h1><div class="overview-hero"><p><img src="'+r+'" alt="MiniTavern Ultra"></p></div><h2 id="アプリ紹介" tabindex="-1">アプリ紹介 <a class="header-anchor" href="#アプリ紹介" aria-label="Permalink to &quot;アプリ紹介&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> は <strong>AI ロールプレイチャット</strong> アプリです。</p><p><strong>AI の相棒を作り、物語を演じる</strong> —— 一文でキャラカードを作るか、主流の v2、v3 を持ち込む。</p><p>GPT、Claude、OpenRouter と、家のローカルモデルにつながる。鍵はスマホに残り、チャットもまず端末に残る。</p><h2 id="できること" tabindex="-1">できること <a class="header-anchor" href="#できること" aria-label="Permalink to &quot;できること&quot;">​</a></h2><ol><li><p><strong>一文で作る、または v2 / v3 を持ち込む</strong><br> 欲しい人を書くと、名前・設定・挨拶が揃う。確認してから話せる。<a href="/ultra_guides/ja/manual/ai-create">AIで作成</a>。PNG / JSON は主流のキャラカード v2、v3 に揃う。<a href="/ultra_guides/ja/manual/chara-card">キャラカード</a>。</p></li><li><p><strong>GPT、Claude、OpenRouter、またはローカル</strong><br> 自分の鍵で直結するか、Ollama / LM Studio につなぐ。鍵は端末の安全な保存領域に置く。<a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。有料枠がないときは <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>；本機は <a href="/ultra_guides/ja/local/">ローカルモデル</a>。</p></li><li><p><strong>ワールドブック、正規表現、プリセット：作成も取り込みも</strong><br><a href="/ultra_guides/ja/manual/lorebook">ワールドブック</a> が設定を支え、<a href="/ultra_guides/ja/manual/regex">正規表現</a> が見せ方を整え、<a href="/ultra_guides/ja/manual/presets">プリセット</a> がプロンプト一式を入れ替える。新規作成も、手元のファイルの取り込みもできる。サンプリングはモデル設定のまま。</p></li><li><p><strong>没入チャット：画像を読み、人を見分け、画像で返す</strong><br> 送った写真を理解し、写っている人を見分ける。キャラも場面に合わせて画像で返信できる。<a href="/ultra_guides/ja/manual/chat">チャット</a>。</p></li><li><p><strong>バックアップとチャットアーカイブ</strong><br><a href="/ultra_guides/ja/manual/backup">全量バックアップ</a> でキャラ、チャット、ワールドブック、正規表現を持ち出す。鍵を含めるかは自分で決める。<a href="/ultra_guides/ja/manual/chat-archive">チャットアーカイブ</a> は既存へ統合するか、新しいチャットとして開ける。</p></li></ol><h2 id="なぜ-minitavern-か" tabindex="-1">なぜ MiniTavern か <a class="header-anchor" href="#なぜ-minitavern-か" aria-label="Permalink to &quot;なぜ MiniTavern か&quot;">​</a></h2><ul><li><strong>カードが速い</strong>：一文で生成、または v2 / v3 を取り込み</li><li><strong>モデルは自分のもの</strong>：GPT、Claude、OpenRouter またはローカル。鍵は端末に</li><li><strong>長編の道具</strong>：ワールドブック、正規表現、プリセット、ペルソナ</li><li><strong>チャットが見る</strong>：画像、人物、画像での返信</li><li><strong>データは持ち出せる</strong>：全量バックアップと単話アーカイブ</li></ul><h2 id="クイックスタート" tabindex="-1">クイックスタート <a class="header-anchor" href="#クイックスタート" aria-label="Permalink to &quot;クイックスタート&quot;">​</a></h2><ol><li><strong>モデルを設定</strong>：設定 → <a href="/ultra_guides/ja/manual/model-link">モデル</a> → モデル接続 → 新規作成して接続テスト、デフォルトに。</li><li><strong>キャラを取り込む／作る</strong>：キャラカード → <a href="/ultra_guides/ja/manual/chara-card">取り込みまたは作成</a>。</li><li><strong>チャット開始</strong>：キャラから開く——寄り添いか本格ロールプレイかはあなた次第。</li></ol><p>詳細は <a href="/ultra_guides/ja/manual/getting-started">はじめての利用</a>。本機配備は左の <strong>ローカルモデル</strong>：<a href="/ultra_guides/ja/local/">概要</a> · <a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a> · <a href="/ultra_guides/ja/local/image-gen/">画像生成</a>。無料枠は <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>。</p><h2 id="ユーザーマニュアル入口" tabindex="-1">ユーザーマニュアル入口 <a class="header-anchor" href="#ユーザーマニュアル入口" aria-label="Permalink to &quot;ユーザーマニュアル入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区分</th><th>説明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/manual/">マニュアルホーム</a></td><td>推奨読書順と総覧</td></tr><tr><td><a href="/ultra_guides/ja/manual/model-link">モデル</a></td><td>接続、パラメータ、接続テストとトラブルシュート</td></tr><tr><td><a href="/ultra_guides/ja/free-cloud/">無料クラウド</a></td><td>各社の無料枠と Key の記入</td></tr><tr><td><a href="/ultra_guides/ja/local/">ローカルモデル</a></td><td>言語 / 画像の本機配備</td></tr><tr><td><a href="/ultra_guides/ja/manual/chara-card">キャラ</a> · <a href="/ultra_guides/ja/manual/ai-create">AIで作成</a></td><td>取り込み、編集、チャット開始、説明から生成</td></tr><tr><td><a href="/ultra_guides/ja/manual/chat">チャット</a> · <a href="/ultra_guides/ja/manual/bubbles">吹き出しと入力欄</a></td><td>対話、見た目、セッション設定</td></tr><tr><td><a href="/ultra_guides/ja/manual/lorebook">上級</a> · <a href="/ultra_guides/ja/manual/presets">Presets</a></td><td>ワールドブック、正規表現、ペルソナ、Presets</td></tr></tbody></table><p>App 内：設定 → <strong>ヘルプとフィードバック</strong> → <strong>ユーザーマニュアル</strong>。</p><h2 id="よくある質問-要約" tabindex="-1">よくある質問（要約） <a class="header-anchor" href="#よくある質問-要約" aria-label="Permalink to &quot;よくある質問（要約）&quot;">​</a></h2><p><strong>Q：MiniTavern Ultra とは？</strong><br> A：AI ロールプレイチャットアプリです。一文でキャラカードを作るか v2 / v3 を取り込み、GPT、Claude、OpenRouter またはローカルモデルで話します。鍵とチャットはまず端末に残ります。</p><p><strong>Q：データは御社サーバーに上がりますか？</strong><br> A：チャット・キャラ・鍵などはデフォルトで端末内。モデル呼び出し時は、あなたが設定した第三者またはローカルアドレスへ送られます。詳しくは <a href="/ultra_guides/ja/privacy">プライバシー</a>。</p><p><strong>Q：API なしでも遊べますか？</strong><br> A：クラウド Key を自前で用意するか、<a href="/ultra_guides/ja/local/">ローカルモデル</a> で PC 上に建ててからスマホ接続が必要です。よくある無料枠は <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>；本機画像は <a href="/ultra_guides/ja/local/image-gen/">画像モデル配備</a>。</p><h2 id="ダウンロードとポリシー" tabindex="-1">ダウンロードとポリシー <a class="header-anchor" href="#ダウンロードとポリシー" aria-label="Permalink to &quot;ダウンロードとポリシー&quot;">​</a></h2><ul><li>トップバー <strong>MiniTavern をダウンロード</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">製品公式サイト</a></li><li><a href="/ultra_guides/ja/privacy">プライバシー</a> · <a href="/ultra_guides/ja/terms">利用規約</a></li></ul>',22)])])}const m=t(n,[["render",o]]);export{_ as __pageData,m as default};
